  let source_path=self.db.path().ok_or("Источник недоступен")?;if !self.db.is_autocommit(){return Err("Источник занят".into())};let mode:String=self.db.query_row("PRAGMA journal_mode",[],|r|r.get(0)).map_err(|_|"Источник недоступен")?;if mode.to_ascii_lowercase()!="delete"{return Err("Источник занят".into())}let pinned=self.source_file.metadata().map_err(|_|"Источник недоступен")?;let current=std::fs::symlink_metadata(source_path).map_err(|_|"Источник недоступен")?;if !same_file(&pinned,&current){return Err("Источник изменился во время проверки".into())}check_snapshot_sidecars(source_path)?;let verified=open_source_sqlite(&self.source_file).map_err(|_|"Источник недоступен")?;verified.pragma_update(None,"key",password).map_err(|_|"Неверный пароль или источник недоступен")?;verified.query_row("SELECT count(*) FROM sqlite_master",[],|r|r.get::<_,i64>(0)).map_err(|_|"Неверный пароль или источник недоступен")?;let original_salt:String=self.db.query_row("PRAGMA cipher_salt",[],|r|r.get(0)).map_err(|_|"Источник недоступен")?;let verified_salt:String=verified.query_row("PRAGMA cipher_salt",[],|r|r.get(0)).map_err(|_|"Источник недоступен")?;if original_salt.is_empty()||original_salt!=verified_salt{return Err("Источник изменился во время проверки".into())}let before=source_stamp(&self.source_file.metadata().map_err(|_|"Источник недоступен")?);
  let pages:i64=self.db.query_row("PRAGMA page_count",[],|r|r.get(0)).map_err(|_|"Не удалось оценить размер")?;let raw:rusqlite::types::Value=self.db.query_row("PRAGMA page_size",[],|r|r.get(0)).map_err(|_|"Не удалось оценить размер")?;let page_size:i64=match raw{rusqlite::types::Value::Integer(n)=>n,rusqlite::types::Value::Text(s)=>s.parse().map_err(|_|"Не удалось оценить размер")?,_=>return Err("Не удалось оценить размер".into())};let estimated=(pages.max(0) as u64).saturating_mul(page_size.max(0) as u64);let parent=destination.parent().ok_or("Папка недоступна")?;let parent=if parent.as_os_str().is_empty(){Path::new(".")}else{parent};let folder=std::fs::File::open(parent).map_err(|_|"Папка недоступна")?;use std::os::fd::AsRawFd;let mut stat=std::mem::MaybeUninit::<libc::statvfs>::uninit();if unsafe{libc::fstatvfs(folder.as_raw_fd(),stat.as_mut_ptr())}!=0{return Err("Не удалось проверить свободное место".into())}let stat=unsafe{stat.assume_init()};let available=(stat.f_bavail as u128)*(stat.f_frsize as u128);#[cfg(feature="test-hook")] let available=std::env::var("ATLAS_TEST_SNAPSHOT_AVAILABLE_BYTES").ok().and_then(|v|v.parse::<u128>().ok()).unwrap_or(available);let required=(estimated as u128)*2+16*1024*1024;if available<required{return Err("Недостаточно свободного места для зашифрованной копии".into())}
