 pub fn snapshot_closed_dir(dir:&std::fs::File,destination:&Path,password:&str,progress:impl FnMut(i32,i32))->Result<(),String>{Self::snapshot_closed_from_dir_name(dir,"workspace.atlas",None,destination,password,progress)}
