  let mut stat=std::mem::MaybeUninit::<libc::statvfs>::uninit();if unsafe{libc::fstatvfs(folder.as_raw_fd(),stat.as_mut_ptr())}!=0{return Err("Не удалось проверить свободное место".into())}let stat=unsafe{stat.assume_init()};let available=(stat.f_bavail as u128)*(stat.f_frsize as u128);if available<(before.2 as u128)+16*1024*1024{return Err("Недостаточно свободного места для зашифрованной копии".into())}
