  source_file.rewind().map_err(|_|"Источник недоступен")?;let mut buf=[0u8;65536];let mut written=0u64;loop{let n=source_file.read(&mut buf).map_err(|_|"Не удалось прочитать источник")?;if n==0{break}target.write_all(&buf[..n]).map_err(|_|"Не удалось записать копию")?;written+=n as u64;progress(((written.saturating_mul(100)/before.2.max(1)).min(100)) as i32,100);}
  target.sync_all().map_err(|_|"Не удалось сохранить копию")?;target.rewind().map_err(|_|"Не удалось проверить копию")?;source_file.rewind().map_err(|_|"Источник недоступен")?;let mut out=[0u8;65536];loop{let n=source_file.read(&mut buf).map_err(|_|"Источник недоступен")?;target.read_exact(&mut out[..n]).map_err(|_|"Копия повреждена")?;if buf[..n]!=out[..n]{return Err("Копия повреждена".into())}if n==0{break}}
  let after=source_file.metadata().map_err(|_|"Источник недоступен")?;let current_fd=unsafe{libc::openat(dir.as_raw_fd(),source_name.as_ptr(),libc::O_RDONLY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if current_fd<0{return Err("Источник изменился во время копирования".into())}let current=unsafe{std::fs::File::from_raw_fd(current_fd)}.metadata().map_err(|_|"Источник недоступен")?;if source_stamp(&after)!=before||!same_file(&after,&current){return Err("Источник изменился во время копирования".into())}check_snapshot_sidecars_at(dir,base)?;folder.sync_all().map_err(|_|"Не удалось сохранить копию")?;Ok(())
