#[cfg(test)] mod streaming_chunk_tests {
 use super::*;
 #[test] fn streaming_chunks_match_previous_algorithm() {
  fn previous(s:&str)->Vec<(usize,String)>{let a:Vec<char>=s.chars().collect();let mut out=vec![];let mut start=0;while start<a.len(){let mut end=(start+400).min(a.len());let word=|c:char|c.is_alphanumeric()||c=='_';if end<a.len()&&word(a[end-1])&&word(a[end]){let mut i=end;while i>start&&word(a[i-1]){i-=1}if i>start{end=i}else{while end<a.len()&&word(a[end]){end+=1}}}out.push((start,a[start..end].iter().collect()));start=end;}out}
  let cases=vec![String::new(),"я".repeat(399),"я".repeat(400),"я".repeat(401),"слово_тест💻 ".repeat(100),format!("{} {} {}", "x".repeat(399),"я".repeat(1200),"конец"),format!("{} aя", "x".repeat(398))];
  for input in cases {let expected=previous(&input);let actual:Vec<_>=chunks(&input).map(|(offset,text)|(offset,text.to_owned())).collect();assert_eq!(actual,expected,"input length {}",input.len());}
 }

}

impl Vault {
 /// Draft bytes remain inside the encrypted database and do not update search.
 pub fn save_note_draft_guarded(&mut self,id:&str,title:&str,text:&str,before_commit:impl FnOnce()->Result<(),String>)->Result<(),String>{
  let tx=self.db.transaction().map_err(|e|e.to_string())?;
  let exists:bool=tx.query_row("SELECT EXISTS(SELECT 1 FROM objects WHERE id=? AND kind='note' AND id NOT IN (SELECT id FROM trash))",[id],|r|r.get(0)).map_err(|e|e.to_string())?;
  if !exists{return Err("Заметка не найдена".into())}
  tx.execute_batch("CREATE TABLE IF NOT EXISTS note_drafts(object_id TEXT PRIMARY KEY,title TEXT NOT NULL,text TEXT NOT NULL)").map_err(|e|e.to_string())?;
  tx.execute("INSERT OR REPLACE INTO note_drafts VALUES(?,?,?)",params![id,title,text]).map_err(|e|e.to_string())?;before_commit()?;tx.commit().map_err(|e|e.to_string())
 }
 pub fn get_note_draft(&self,id:&str)->Result<Option<(String,String)>,String>{use rusqlite::OptionalExtension;let exists:bool=self.db.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='note_drafts')",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !exists{return Ok(None)}self.db.query_row("SELECT title,text FROM note_drafts WHERE object_id=?",[id],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(|e|e.to_string())}
 pub fn clear_note_draft_guarded(&mut self,id:&str,title:&str,text:&str,before_commit:impl FnOnce()->Result<(),String>)->Result<bool,String>{let tx=self.db.transaction().map_err(|e|e.to_string())?;let exists:bool=tx.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='note_drafts')",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !exists{return Ok(false)}let removed=tx.execute("DELETE FROM note_drafts WHERE object_id=? AND title=? AND text=?",params![id,title,text]).map_err(|e|e.to_string())?>0;before_commit()?;tx.commit().map_err(|e|e.to_string())?;Ok(removed)}
}
impl Vault {
 pub fn list_note_drafts(&self)->Result<Vec<(String,String,String)>,String>{let exists:bool=self.db.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='note_drafts')",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !exists{return Ok(vec![])}let mut s=self.db.prepare("SELECT note_drafts.object_id,note_drafts.title,note_drafts.text FROM note_drafts JOIN objects ON objects.id=note_drafts.object_id WHERE objects.kind='note' AND objects.id NOT IN (SELECT id FROM trash) ORDER BY objects.id").map_err(|e|e.to_string())?;let rows=s.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|e|e.to_string())?;rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())}
 pub fn recover_note_drafts_guarded(&mut self,guard:impl Fn()->Result<(),String>)->Result<usize,String>{let drafts=self.list_note_drafts()?;let mut count=0;for(id,title,text)in drafts{self.put_note_guarded(&id,&title,&text,||guard())?;if self.clear_note_draft_guarded(&id,&title,&text,||guard())?{count+=1;}}Ok(count)}
}

#[cfg(test)] mod incremental_block_tests {
 use super::*; use sha2::{Digest,Sha256};
 #[test] fn only_changed_blocks_written_and_rollback_preserves_index(){
  let path=std::env::temp_dir().join(format!("atlas-block-test-{}",std::process::id())); let _=std::fs::remove_file(&path); let mut v=Vault::create(&path,"test-password").unwrap();
  v.db.execute_batch("CREATE TEMP TABLE changes(n INTEGER); CREATE TEMP TRIGGER changed AFTER UPDATE ON faiss_blocks BEGIN INSERT INTO changes VALUES(new.n); END; CREATE TEMP TRIGGER removed AFTER DELETE ON faiss_blocks BEGIN INSERT INTO changes VALUES(old.n); END;").unwrap();
  let mut bytes=vec![42u8;BLOCK*3]; let meta=|b:&[u8]|serde_json::json!({"index_sha256":format!("{:x}",Sha256::digest(b))}); v.save_semantic(&bytes,&meta(&bytes)).unwrap();
  bytes[BLOCK+20]=7; v.save_semantic(&bytes,&meta(&bytes)).unwrap(); let changes:Vec<i64>=v.db.prepare("SELECT n FROM changes").unwrap().query_map([],|r|r.get(0)).unwrap().map(Result::unwrap).collect(); assert_eq!(changes,vec![1]);
  let mut changed=bytes.clone(); changed[2*BLOCK+2]=1; assert!(v.save_semantic_guarded(&changed,&meta(&changed),||Err("stop".into())).is_err()); let actual:Vec<u8>=v.db.query_row("SELECT data FROM faiss_blocks WHERE n=2",[],|r|r.get(0)).unwrap(); assert_eq!(actual,bytes[2*BLOCK..]); drop(v); std::fs::remove_file(path).unwrap();
 }
}

