 #[test] fn encrypted_plain_encrypted_preserves_semantic_after_update(){let root=std::env::temp_dir().join(format!("atlas-sem-roundtrip-{}",std::process::id()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("a"),"password").unwrap();v.set_workspace_name_guarded("test",||Ok(())).unwrap();v.put_note("00000000-0000-4000-8000-000000000001","title","data").unwrap();let mut idx=atlas_faiss_probe::Index::new().unwrap();let mut vector=[0f32;512];vector[4]=1.;idx.add(&[vector]).unwrap();let bytes=idx.to_memory().unwrap();let m=serde_json::json!({"key":"test","index_sha256":format!("{:x}",Sha256::digest(&bytes)),"records":[{"id":"00000000-0000-4000-8000-000000000001"}]});v.save_semantic(&bytes,&m).unwrap();v.save_semantic(&bytes,&m).unwrap();v.export_plain(&root.join("plain")).unwrap();let copied=Vault::import_plain(&root.join("plain"),&root.join("b"),"password").unwrap();let (index,meta)=copied.load_semantic().unwrap();assert_eq!(index.reconstruct(0).unwrap(),vector);assert_eq!(meta,m);drop(copied);drop(v);std::fs::remove_dir_all(root).unwrap();}
